package langcode

import "strings"

//go:generate sh -c "go run ./cldrgen -zip \"$CLDR_ZIP\" -out cldr_table.go"

// Locale is the CLDR data the QA checks need to read numbers, dates and times
// the way a language writes them. cldr_table.go holds it, generated by
// cldrgen from a pinned CLDR JSON release (see cldrgen for how to run it).
type Locale struct {
	// Decimal and Group are the decimal and grouping separators of Latin
	// digits. Group may be a space (U+00A0, U+202F) or an apostrophe.
	Decimal, Group rune
	// NativeDigits is set when the language's default digits are not Latin
	// (Arabic, Persian): its numbers may use other separators.
	NativeDigits bool
	// MinGrouping is CLDR's minimumGroupingDigits: 2 means a four-digit
	// number is written without a grouping separator ("1000" in Spanish).
	MinGrouping int
	// DateOrder is the field order of the short date: "mdy", "dmy" or "ymd".
	DateOrder string
	// Hour12 is set when the short time uses a 12-hour clock.
	Hour12 bool
	// AM and PM are the day-period markers, every form CLDR lists.
	AM, PM []string
	// Months holds, for each month, every name CLDR lists: wide and
	// abbreviated, format and stand-alone.
	Months [12][]string
}

// LocaleFor returns the CLDR data for a language code ("de", "pt-br",
// "zh-hans"), falling back through CLDR's parent locales to the base
// language. ok is false when CLDR has no data for the language.
func LocaleFor(code string) (Locale, bool) {
	code = Normalize(code)
	for code != "" {
		if l, ok := cldrLocales[code]; ok {
			return l, true
		}
		code = cldrParent(code)
	}
	return Locale{}, false
}

// cldrParent is the locale code falls back to: CLDR's explicit parent
// ("en-gb" → "en-001", "pt-ao" → "pt-pt"), else the code without its last
// subtag, else "".
func cldrParent(code string) string {
	if p, ok := cldrParents[code]; ok {
		if p == "root" {
			return ""
		}
		return p
	}
	if i := strings.LastIndexByte(code, '-'); i > 0 {
		return code[:i]
	}
	return ""
}
